import sys

def match(pattern, query, good_set):
    if '*' not in pattern:
        if len(pattern) != len(query):
            return False
        for p, q in zip(pattern, query):
            if p != '?' and p != q and q not in good_set:
                return False
        return True
    else:
        star_index = pattern.index('*')
        prefix = pattern[:star_index]
        suffix = pattern[star_index + 1:]
        prefix_length = len(prefix)
        suffix_length = len(suffix)
        if len(query) < prefix_length + suffix_length:
            return False
        for i in range(len(query) - suffix_length + 1):
            if all(p == '?' or p == q or q in good_set for p, q in zip(prefix, query[:i])) and \
               all(s == '?' or s == q or q in good_set for s, q in zip(suffix, query[i + len(prefix):])):
                return True
        return False

good_letters = sys.stdin.readline().strip()
pattern = sys.stdin.readline().strip()
n = int(sys.stdin.readline().strip())
queries = [sys.stdin.readline().strip() for _ in range(n)]

good_set = set(good_letters)

for query in queries:
    print('YES' if match(pattern, query, good_set) else 'NO')
